{"command": "cat > /tmp/expect_alpine.tcl <<'EOF'
#!/usr/bin/expect -f
set timeout 120
log_user 1
spawn telnet 127.0.0.1 5555
# handle telnet negotiation; wait for login prompt
expect {
    -re "login:" {}
    -re "localhost login:" {}
    -re "Alpine" {}
    timeout { puts "timeout waiting for login"; exit 1 }
}
# if saw banner but no login, wait for login
expect {
    -re "login:" {}
    -re "localhost login:" {}
    timeout { }
}
send "root\r"
# wait for shell prompt
expect {
    -re "# $" {}
    -re "#" {}
    timeout { puts "timeout waiting for shell"; exit 1 }
}
# set password and enable ssh
send "passwd\r"
expect {
    -re "New password:" {}
    timeout { puts "timeout waiting for new password"; exit 1 }
}
send "password123\r"
expect {
    -re "Retype new password:" {}
    timeout { puts "timeout waiting for retype"; exit 1 }
}
send "password123\r"
expect {
    -re "passwd: password updated successfully" {}
    -re "#" {}
    timeout { puts "timeout waiting for passwd result"; exit 1 }
}
# ensure ssh server installed and running
send "setup-sshd -c openssh\r"
expect {
    -re "Starting sshd" {}
    -re "sshd" {}
    -re "#" {}
    timeout { puts "timeout waiting for setup-sshd"; exit 1 }
}
# force enable and start
send "/etc/init.d/sshd restart\r"
expect {
    -re "Starting sshd" {}
    -re "OK" {}
    -re "#" {}
    timeout { puts "timeout waiting for sshd restart"; exit 1 }
}
# ensure root login allowed
send "grep -q '^PermitRootLogin' /etc/ssh/sshd_config && sed -i 's/^PermitRootLogin.*/PermitRootLogin yes/' /etc/ssh/sshd_config || echo 'PermitRootLogin yes' >> /etc/ssh/sshd_config\r"
expect {
    -re "#" {}
    timeout { puts "timeout waiting for config edit"; exit 1 }
}
send "/etc/init.d/sshd restart\r"
expect {
    -re "#" {}
    timeout { puts "timeout waiting for sshd restart after config"; exit 1 }
}
# ensure password auth enabled
send "grep -q '^PasswordAuthentication' /etc/ssh/sshd_config && sed -i 's/^PasswordAuthentication.*/PasswordAuthentication yes/' /etc/ssh/sshd_config || echo 'PasswordAuthentication yes' >> /etc/ssh/sshd_config\r"
expect {
    -re "#" {}
    timeout { puts "timeout waiting for password auth config"; exit 1 }
}
send "/etc/init.d/sshd restart\r"
expect {
    -re "#" {}
    timeout { puts "timeout waiting for sshd restart final"; exit 1 }
}
# keep session open
send "echo ready\r"
expect {
    -re "ready" {}
    timeout { puts "timeout waiting for ready"; exit 1 }
}
# exit gracefully
send "exit\r"
expect eof
EOF
chmod +x /tmp/expect_alpine.tcl
"}

